using System;using System.IO;using System.Text;using UnityEngine;using UnityEditor;
public static class ValidateFieldTooltips {
 static void Check(UnityEngine.Object target,string path,StringBuilder b){var so=new SerializedObject(target);var p=so.FindProperty(path);if(p==null||string.IsNullOrWhiteSpace(p.tooltip))throw new Exception("Inspector tooltip missing: "+target.name+"."+path);b.AppendLine(target.name+"."+path+" = "+p.tooltip);}
 public static string Run(){if(EditorApplication.isPlaying||EditorUtility.scriptCompilationFailed)throw new Exception("Compiled Edit Mode required");var b=new StringBuilder();var camera=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Mock/Prefabs/Manager/CameraManager.prefab");Check(camera.GetComponent<VictoryCameraRig>(),"_moveDuration",b);Check(camera.GetComponent<VictoryCameraRig>(),"_sideAngle",b);Check(camera.GetComponent<VictoryContrast>(),"_hold",b);var overlay=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Mock/UI/FinalBlowOverlay.prefab");Check(overlay.GetComponentInChildren<FinalBlowPresentation>(true),"_textStartScale",b);var status=AssetDatabase.LoadAssetAtPath<PlayerStatus>("Assets/Mock/ScriptableObjects/PlayerStatus.asset");Check(status,"_maxHealth",b);Check(status,"_skillGaugeCost._healGaugePerPercent",b);var state=AssetDatabase.LoadAssetAtPath<PlayerStateConfig>("Assets/Mock/ScriptableObjects/PlayerStateConfig.asset");Check(state,"_lightAttackClips._comboWindowDelaySeconds",b);var audio=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Mock/Prefabs/Manager/AudioManager.prefab");Check(audio.GetComponent<AudioManager>(),"seList",b);AssetDatabase.SaveAssets();b.AppendLine("PASS: native SerializedProperty.tooltip on saved Prefab/ScriptableObject, including nested serialized settings. Compile errors=0; Edit Mode; saved.");File.WriteAllText("AgentScripts/FieldTooltipTests.txt",b.ToString());return b.ToString();}
}
